import sys

def solve():
    n = int(sys.stdin.readline())
    b = list(map(int, sys.stdin.readline().split()))
    b_sorted = sorted(b)
    from collections import defaultdict
    freq = defaultdict(int)
    for num in b:
        freq[num] += 1

    def backtrack(pos, current_xor, last_a):
        if pos == n:
            return True
        for num in freq:
            if freq[num] == 0:
                continue
            new_xor = current_xor ^ num
            if new_xor > last_a:
                freq[num] -= 1
                if backtrack(pos + 1, new_xor, new_xor):
                    return True
                freq[num] += 1
        return False

    def find_permutation():
        for perm in permutations(b):
            current_xor = 0
            last_a = 0
            valid = True
            for num in perm:
                current_xor ^= num
                if current_xor <= last_a:
                    valid = False
                    break
                last_a = current_xor
            if valid:
                return perm
        return None

    from itertools import permutations
    if n <= 20:
        perm = find_permutation()
        if perm is not None:
            print("Yes")
            print(' '.join(map(str, perm)))
            return
        else:
            print("No")
            return

    if not backtrack(0, 0, 0):
        print("No")
        return

    # Try to find a valid permutation using a greedy approach
    b_sorted = sorted(b)
    used = [False] * n
    res = []
    current_xor = 0
    last_a = 0
    for _ in range(n):
        found = False
        for i in range(n):
            if not used[i]:
                new_xor = current_xor ^ b_sorted[i]
                if new_xor > last_a:
                    res.append(b_sorted[i])
                    used[i] = True
                    current_xor = new_xor
                    last_a = new_xor
                    found = True
                    break
        if not found:
            print("No")
            return
    print("Yes")
    print(' '.join(map(str, res)))

solve()
